Index: web/index.html
===================================================================
--- web/index.html	
+++ web/index.html	
@@ -0,0 +1,77 @@
+<!DOCTYPE html>
+<html lang="zh-CN">
+<head>
+  <meta charset="UTF-8">
+  <meta name="viewport" content="width=device-width, initial-scale=1.0">
+  <title>待办事项</title>
+  <style>
+    * { margin: 0; padding: 0; box-sizing: border-box; }
+    body { font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif; background: #f5f5f5; padding: 40px 20px; }
+    .container { max-width: 500px; margin: 0 auto; background: #fff; border-radius: 8px; box-shadow: 0 2px 8px rgba(0,0,0,0.1); padding: 30px; }
+    h1 { text-align: center; color: #333; margin-bottom: 20px; font-size: 1.6em; }
+    .input-row { display: flex; gap: 10px; margin-bottom: 20px; }
+    .input-row label { position: absolute; width: 1px; height: 1px; overflow: hidden; clip: rect(0,0,0,0); }
+    #todoInput { flex: 1; padding: 10px 14px; border: 2px solid #ddd; border-radius: 6px; font-size: 15px; outline: none; transition: border-color 0.2s; }
+    #todoInput:focus { border-color: #4a90d9; }
+    #addBtn { padding: 10px 22px; background: #4a90d9; color: #fff; border: none; border-radius: 6px; font-size: 15px; cursor: pointer; transition: background 0.2s; }
+    #addBtn:hover { background: #357abd; }
+    .count { color: #888; font-size: 14px; margin-bottom: 12px; }
+    #todoList { list-style: none; }
+    #todoList li { display: flex; align-items: center; justify-content: space-between; padding: 12px 14px; background: #fafafa; border: 1px solid #eee; border-radius: 6px; margin-bottom: 8px; font-size: 15px; }
+    .task-text { flex: 1; color: #333; }
+    .delete-btn { background: #e74c3c; color: #fff; border: none; border-radius: 4px; padding: 5px 12px; font-size: 13px; cursor: pointer; transition: background 0.2s; }
+    .delete-btn:hover { background: #c0392b; }
+    .empty { text-align: center; color: #bbb; padding: 20px 0; font-size: 14px; }
+  </style>
+</head>
+<body>
+  <div class="container">
+    <h1>待办事项</h1>
+    <div class="input-row">
+      <label for="todoInput">待办事项</label>
+      <input type="text" id="todoInput" placeholder="输入待办事项...">
+      <button id="addBtn">添加</button>
+    </div>
+    <div class="count">共 <span id="todoCount">0</span> 个任务</div>
+    <ul id="todoList"></ul>
+    <div id="emptyMsg" class="empty">暂无任务，添加一个吧！</div>
+  </div>
+  <script>
+    (function() {
+      var input = document.getElementById('todoInput');
+      var addBtn = document.getElementById('addBtn');
+      var list = document.getElementById('todoList');
+      var countEl = document.getElementById('todoCount');
+      var emptyMsg = document.getElementById('emptyMsg');
+
+      function updateCount() {
+        var items = list.querySelectorAll('li');
+        countEl.textContent = items.length;
+        emptyMsg.style.display = items.length === 0 ? 'block' : 'none';
+      }
+
+      function addItem() {
+        var text = input.value.trim();
+        if (!text) return;
+        var li = document.createElement('li');
+        li.innerHTML = '<span class="task-text"></span><button class="delete-btn">删除</button>';
+        li.querySelector('.task-text').textContent = text;
+        li.querySelector('.delete-btn').addEventListener('click', function() {
+          li.remove();
+          updateCount();
+        });
+        list.appendChild(li);
+        input.value = '';
+        input.focus();
+        updateCount();
+      }
+
+      addBtn.addEventListener('click', addItem);
+      input.addEventListener('keydown', function(e) {
+        if (e.key === 'Enter') addItem();
+      });
+      updateCount();
+    })();
+  </script>
+</body>
+</html>

